mapper.select:
SELECT problem_id, exists_flag, del_flag, auth, title, checked_at, requested_at
FROM solution_problem_reference
WHERE checked_at <= #{cutoff}

    AND (checked_at > #{cursorCheckedAt}
         OR (checked_at = #{cursorCheckedAt} AND problem_id > #{cursorProblemId}))

ORDER BY checked_at ASC, problem_id ASC
LIMIT #{limit}
